import { z } from "zod";
const zAudioProps = z.object({
    src: z.string().url(),
    label: z.string().optional(),
    caption: z.string().optional(),
    size: z.enum(["s", "m", "l"]).default("m"),
    group: z.string().or(z.literal(false)).optional(),
});
export function AudioWidget(define) {
    return define("Audio")
        .props(zAudioProps)
        .shared({
        val: z.number(),
        played: z.number(),
        playing: z.boolean(),
    })
        .defaults(() => ({ val: 0, played: 0, playing: false }))
        .userEvents({
        pause: [z.literal(true), false],
        play: [z.literal(true), false],
    })
        .methods({
        seekTo: (cmd, [time]) => cmd("seekTo", [time]),
        play: (cmd) => cmd("play"),
        pause: (cmd) => cmd("pause"),
    })
        .render((props) => ({
        id: props.id,
        label: props.label,
        caption: props.caption,
        size: props.size,
        src: props.src,
        group: props.group,
    }));
}
